import pathlib,subprocess,re,collections
paths=subprocess.check_output(['git','ls-files','--others','--exclude-standard','-z']).decode().split('\0')
patterns={'private_key':r'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----','github_token':r'gh[pousr]_[A-Za-z0-9]{30,}','openai_key':r'sk-(?:proj-|or-v1-)?[A-Za-z0-9_-]{35,}','jwt':r'eyJ[A-Za-z0-9_-]{20,}\.eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{15,}'}
hits=collections.Counter(); files=[]
for p in paths:
 if not p: continue
 f=pathlib.Path(p)
 if not f.is_file() or f.is_symlink():continue
 try:s=f.read_text()
 except:continue
 keys=[k for k,v in patterns.items() if re.search(v,s)]
 if keys:files.append((p,keys));hits.update(keys)
print('Secret pattern counts:',dict(hits))
for p,k in files[:70]:print(p,','.join(k))
